(() => {
  'use strict';
  const data = window.PORTFOLIO, main = document.querySelector('main');
  let lang = 'zh', filter = 'all', galleryFilter = 'all', guideHistory = [];
  try { lang = localStorage.getItem('yajing-language') || 'zh'; } catch {}
  if (!['zh','en'].includes(lang)) lang='zh';
  const tr = (zh,en) => lang === 'zh' ? zh : en;
  const esc = text => String(text ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const title = p => tr(p.title,p.titleEn);
  const projectLink = p => `#/project/${p.id}`;
  const chips = p => (tr(p.tags,p.tagsEn)).map(t=>`<span class="tag">${esc(t)}</span>`).join('');
  const image = (src,caption,cls='') => `<figure class="gallery-card ${cls}"><button class="gallery-button" data-image="${esc(src)}" data-caption="${esc(caption)}" aria-label="${esc(tr('放大图片：','Enlarge: ')+caption)}"><img src="${esc(src)}" alt="${esc(caption)}" loading="lazy"></button><figcaption>${esc(caption)}</figcaption></figure>`;
  const gallery = [
    {type:'ai',src:'assets/xiaomi-polaroid.png',caption:'小米 · 3D旅行拍立得 / 项目视觉'},
    {type:'campaign',src:'assets/heritage-posters.png',caption:'百度 · AI非遗馆 / 传播视觉'},
    {type:'ai',src:'assets/breakfast-scene.png',caption:'AI商业内容 · 早餐短剧 / 场景资产'}
  ];
  function updateChrome(){
    const labels={home:tr('首页','Home'),approach:tr('能力与方法','Approach'),cases:tr('作品与项目','Work'),lab:tr('创作','Lab'),about:tr('关于我','About'),resume:tr('简历 ↗','Resume ↗'),brief:tr('快速了解我','Quick introduction'),contact:tr('联系我 ↗','Contact ↗')};
    document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=labels[e.dataset.i18n]);
    document.documentElement.lang=lang==='zh'?'zh-CN':'en';
    document.querySelector('.language').textContent=tr('EN','中');
    document.querySelector('.guide-label').textContent=tr('作品集导览','Portfolio guide');
  }
function row(p,i){return `<a class="project-row reveal" style="animation-delay:${i*45}ms" href="${projectLink(p)}"><div class="project-preview ${p.cover?'':'preview-type'}">${p.cover?`<img src="${esc(p.cover)}" alt="${esc(tr(p.coverLabel,p.titleEn))}" loading="lazy">`:`<span>${esc(p.company)}<strong>${p.id==='baike'?'Creators.':'Growth.'}</strong><small>${esc(p.category)}</small></span>`}</div><div class="project-marker">${p.id==='xiaomi'?'<span class="pin">↳ SELECTED</span>':''}<span class="project-category">${esc(p.category)}</span><span class="project-company">${esc(p.company)}</span></div><div><h3>${esc(title(p))}</h3><p class="card-focus">${esc(tr(p.cardFocus,p.category))}</p><p>${esc(tr(p.cardSummary,p.cardSummaryEn))}</p></div><div class="row-meta">${p.cardMetrics.slice(0,2).map(m=>`<div class="row-result"><b>${esc(tr(m[0],m[2]))}</b><span>${esc(tr(m[1],m[3]))}</span></div>`).join('')}<span class="row-cta">${tr('查看完整案例','Read case')} ↗</span></div><span class="row-symbol" aria-hidden="true">${p.icon}</span></a>`;}
  function filteredProjects(){const ps=data.projects.filter(p=>filter==='all'||p.id===filter||(filter==='ai'&&['xiaomi','heritage','nova'].includes(p.id)));return ps.map(row).join('');}
  function filterButtons(){return [['all','全部','All'],['ai','AI产品与GTM','AI & GTM'],['futu','内容增长','Content growth'],['baike','创作者运营','Creators']].map(([key,zh,en])=>`<button class="filter" data-filter="${key}" aria-pressed="${filter===key}">${tr(zh,en)}</button>`).join('');}
  const workGroups=[['ai','AI PRODUCT EXPERIENCE','AI产品与体验','AI Product Experience',['xiaomi']],['growth','CREATORS & GROWTH','创作者与增长','Creators & Growth',['baike','futu']],['story','CONTENT & COMMUNICATION','内容与传播','Content & Communication',['heritage','nova']]];
  function home(){return `<div class="page-enter home-editorial"><section class="hero"><div class="hero-copy"><p class="eyebrow">${tr('AI产品运营 / 创作者生态 / 内容驱动增长','AI PRODUCT OPERATIONS / CREATOR ECOSYSTEMS / CONTENT-LED GROWTH')}</p><h1 class="home-value">${tr('<span>让产品价值</span><span>被理解，被体验，</span><em>被更多人使用。</em>','<span>Make product value</span><span>understood. Experienced.</span><em>Used by more people.</em>')}</h1><p class="hero-sub">${tr('我是邱雅婧，关注AI能力如何进入真实的用户场景。做过AI玩法策划与效果评测，也参与过创作者运营和产品传播，希望通过内容与运营，让用户理解产品、参与体验，并进一步采取行动。','I’m Janice Qiu. I explore how AI capabilities enter real user scenarios through experience planning, output evaluation, creator operations and product communication. I use content and operations to help people understand, try and act on product value.')}</p><div class="home-actions"><a class="primary-button" href="#/about">${tr('认识我','About me')} ↗</a><a class="text-link" href="#/work">${tr('浏览我的项目','Explore my projects')} ↗</a></div></div><div class="direction-cards" aria-label="${tr('探索作品方向','Explore my work')}">${workGroups.map(([id,en,zh,label],i)=>`<a class="direction-card" href="#/work?section=work-${id}"><img src="${['assets/janice-personal-2.jpg','assets/janice-personal-4.jpg','assets/janice-personal-3.jpg'][i]}" alt=""><span class="direction-number">0${i+1} /</span><div class="direction-caption"><span>${en}</span><h2>${tr(['查看 AI 项目','查看运营实践','查看内容作品'][i],['View AI projects','Explore operations','View creative work'][i])}</h2><p>${tr(['从用户场景出发，把AI能力转化为具体玩法，并通过效果评测与体验检查推动落地。','连接创作者、内容与产品，让持续的内容供给承接用户兴趣与使用需求。','用场景、故事和真实案例解释产品价值，让技术与功能更容易被理解和分享。'][i],['From user scenarios to useful AI experiences.','Connecting people, creators and content through operating mechanisms.','Making complex ideas clear, accessible and worth sharing.'][i])}</p><span class="direction-category">${tr(zh,label)}</span></div></a>`).join('')}</div></section><div class="home-note"><span>CREATING, ALWAYS.</span><span>${tr('从理解需求，到推动体验发生。','From understanding needs to making experiences happen.')}</span></div></div>`;}
  function listingCard(p){return `<article class="listing-project"><a class="listing-visual" href="${projectLink(p)}" aria-label="${esc(tr('查看完整案例：','Read case: ')+title(p))}">${p.cover?`<img src="${esc(p.cover)}" alt="${esc(tr(p.coverLabel,p.titleEn))}" loading="lazy">`:`<span>${esc(p.company)}<strong>${p.id==='baike'?'Creators.':'Growth.'}</strong></span>`}</a><div class="listing-copy"><h3><a href="${projectLink(p)}">${esc(title(p))}</a></h3><p class="listing-focus">${esc(tr(p.cardFocus,p.category))}</p><p>${esc(tr(p.cardSummary,p.summaryEn))}</p>${p.listingMetrics.length?`<div class="listing-metrics">${p.listingMetrics.map(([n,zh,ne,en])=>`<div><strong>${esc(tr(n,ne))}</strong><span>${esc(tr(zh,en))}</span></div>`).join('')}</div>`:''}<details class="listing-expansion"><summary>${tr('展开介绍','More about this project')}<span aria-hidden="true">＋</span></summary><div>${copyHTML(tr(p.listingExpansion,p.listingExpansionEn))}<a class="text-link" href="${projectLink(p)}">${tr('查看完整案例','Read full case')} ↗</a></div></details><a class="listing-case-link text-link" href="${projectLink(p)}">${tr('查看完整案例','Read full case')} ↗</a></div></article>`;}
  function work(){return `<article id="projects" class="work-page page-enter"><header class="editorial-intro"><span class="eyebrow">${tr('作品与项目','Selected Work')}</span><h1>${tr('让想法进入真实场景','Ideas in real situations.')}</h1><p>${tr('这些项目记录了我如何理解用户需求、组织内容与协作，并把产品能力转化为可以体验、参与和传播的具体成果。','These projects show how I understand user needs, organize content and collaboration, and turn capabilities into experiences people can use and share.')}</p></header><div class="work-layout"><aside class="work-sidebar"><nav class="work-index" aria-label="${tr('项目分类','Project categories')}">${workGroups.map(([id,en,zh,label],i)=>`<a href="#/work?section=work-${id}">0${i+1} ${tr(zh,label)} ↘</a>`).join('')}</nav></aside><div>${workGroups.map(([id,en,zh,label,ids],i)=>`<section id="work-${id}" class="work-group"><header><span class="eyebrow">0${i+1} / ${en}</span><h2>${tr(zh,label)}</h2><p>${tr(['从用户愿意尝试的场景出发，参与玩法策划、效果评测与上线体验，让AI能力变成具体的使用理由。','把内容生产、创作者协作与产品目标连接起来，关注内容如何持续供给，以及用户如何从感兴趣走向进一步行动。','把产品能力放进具体情境，用玩法、案例与创作者表达，帮助用户理解产品可以做什么。'][i],['AI experiences built around reasons people want to try them.','Connecting content supply, creator collaboration and product goals.','Explaining product capabilities through scenarios and real examples.'][i])}</p></header>${ids.map(id=>listingCard(data.projects.find(p=>p.id===id))).join('')}</section>`).join('')}<section class="lab-invitation"><span class="eyebrow">CREATIVE LAB</span><h2>${tr('账号与内容实验','Accounts & content experiments')}</h2><p>${tr('在项目之外，我也通过账号实践观察选题、表达形式与用户反馈，持续尝试AI辅助创作和不同平台的内容表达。','Outside project work, I use account experiments to explore topics, formats and user feedback.')}</p><div class="listing-metrics"><div><strong>1200+</strong><span>${tr('AI孵化账号单月合计涨粉','Combined monthly follower growth')}</span></div><div><strong>${tr('1.3万+','13K+')}</strong><span>${tr('个人内容单篇互动','Interactions on a personal post')}</span></div></div><a class="text-link" href="#/lab">${tr('查看账号与作品','Explore accounts & creative work')} ↗</a></section></div></div><section class="page-end"><h2>${tr('项目背后，是不断积累的工作方法','Behind each project is a developing way of working.')}</h2><p class="work-closing">${tr('从需求出发，用场景解释产品，用内容连接用户，再通过结果与反馈调整下一步。','Start with needs, explain products through scenarios, connect with people through content, and refine the next step through feedback.')}</p><a class="text-link" href="#/approach">${tr('了解我的做事方式','How I work')} ↗</a> <a class="text-link" href="#/contact">${tr('联系我','Contact me')} ↗</a></section></article>`;}
  function galleryMarkup(){return gallery.filter(g=>galleryFilter==='all'||g.type===galleryFilter).map(g=>image(g.src,g.caption)).join('');}
  function phaseCompare(){return `<div class="phase-compare"><div class="eyebrow">ITERATION / ${tr('两轮内容节奏','Content timing')}</div><div class="phase-buttons"><button data-phase="1" aria-pressed="true">Phase 01 · Bullish</button><button data-phase="2" aria-pressed="false">Phase 02 · Figure + Gemini</button></div><div class="phase-line"><span id="phase-pre">${tr('上市前','Pre-IPO')} <b>15%</b></span><span id="phase-post">${tr('上市后','Post-IPO')} <b>85%</b></span></div><div class="phase-bar" style="--pre:15%" role="img" aria-label="上市前15%，上市后85%"><span></span><span></span></div><p class="phase-caption" id="phase-caption">${tr('第一轮集中于上市后中签与收益讨论。点击第二阶段，查看如何提前覆盖用户信息需求。','The first phase focused on post-IPO outcomes. Switch phases to see the earlier content coverage.')}</p></div>`;}
  function evaluation(){return `<div class="evaluation"><div class="eyebrow">MODEL EVALUATION / ${tr('评估方法','Evaluation approach')}</div><div class="evaluation-tabs" role="group" aria-label="查看评估内容"><button data-evaluation="criteria" aria-pressed="true">${tr('评估维度','Criteria')}</button><button data-evaluation="issues" aria-pressed="false">${tr('问题与反馈','Issues & feedback')}</button><button data-evaluation="finding" aria-pressed="false">${tr('测试发现','Test finding')}</button></div><div id="evaluation-content">${evaluationContent('criteria')}</div></div>`;}
  function evaluationContent(mode){const items={criteria:[tr('把“好不好看”拆成可观察的维度','Translate quality into observable criteria'),['成图率与主体识别准确度','人物比例、构图与风格一致性','多人完整性、肢体畸变和宠物异常']],issues:[tr('用具体问题支持迭代','Turn observations into actionable feedback'),['发现部分风格头部比例偏大','多人物场景出现漏人与稳定性不足','整理风格不一致及宠物畸变，反馈优化方向']],finding:[tr('按场景比较，而非只看优秀样例','Compare scenarios, not just the best outputs'),['同一测试中，盲盒风格单人比例合适率：小爱50%，同期GPT 57.5%','特定测试集结果，不等同于线上整体成功率','按主体和风格拆分测试，补充问题场景']]};const [heading,lines]=items[mode]||items.criteria;if(mode==='issues')return modelFeedback();return `<h3>${esc(heading)}</h3><ul>${lines.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${mode==='finding'?'<div class="comparison-numbers"><div><b>50%</b><span>小爱 · 单人比例合适率</span></div><div><b>57.5%</b><span>同期GPT · 相同测试口径</span></div></div>':''}`;}

  function modelFeedback(){const p=data.projects.find(p=>p.id==='xiaomi');return `<h3>${tr('把体验问题转成可跟进的反馈','Turn experience issues into actionable feedback')}</h3><div class="feedback-table-wrap"><table class="feedback-table"><thead><tr><th>发现的问题</th><th>评测及处理方式</th><th>跟进结果</th></tr></thead><tbody>${p.modelFeedback.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="data-note">${esc(p.modelNote)}</p>`;}
  function markdownNotes(text){
    const inline=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
    const out=[];let paragraph=[],list=false;
    const flush=()=>{if(paragraph.length){out.push('<p>'+paragraph.map(inline).join('<br>')+'</p>');paragraph=[];}};
    for(const raw of text.split(/\r?\n/)){
      const line=raw.trim();
      if(!line||line==='---'){flush();if(list){out.push('</ul>');list=false;}continue;}
      if(line.startsWith('- ')){flush();if(!list){out.push('<ul>');list=true;}out.push('<li>'+inline(line.slice(2))+'</li>');continue;}
      if(list){out.push('</ul>');list=false;}
      if(/^#{2,4} /.test(line)){flush();out.push('<h3>'+inline(line.replace(/^#+ /,''))+'</h3>');}else paragraph.push(line);
    }
    flush();if(list)out.push('</ul>');return out.join('');
  }
  function videoCard(video){
    return `<article class="video-work"><a class="video-preview" href="${esc(video.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc('在抖音观看：'+video.title)}"><img src="${esc(video.poster)}" alt="早餐短剧项目场景素材，非视频截图" loading="lazy"><span class="video-play" aria-hidden="true">▶</span><span class="video-platform">${tr('在抖音观看 ↗','Watch on Douyin ↗')}</span></a><div class="video-copy"><span class="eyebrow">DOUYIN / PROJECT VIDEO</span><h3>${esc(video.title)}</h3>${video.role?`<p class="video-role">${esc(video.role)}</p>`:''}<p>${esc(video.description)}</p><div class="tags">${video.tags.map(t=>`<span class="tag"># ${esc(t)}</span>`).join('')}</div><a class="text-link" href="${esc(video.url)}" target="_blank" rel="noopener noreferrer">${tr('打开抖音成片','Open project video')} ↗</a><p class="subtle-note">${tr('封面使用项目场景素材；点击前往抖音观看成片。','Cover uses a project scene asset. Open Douyin to watch the video.')}</p></div></article>`;
  }
  function contentMatrix(project){
    return `<div class="content-matrix"><div class="eyebrow">CONTENT MATRIX / UGC视角</div><h3>从用户需求出发，组织三类内容</h3><p>用教程解释产品，用互动承接讨论，再将产品能力融入具体的个股场景。</p><div class="content-example-grid">${project.contentExamples.map((e,i)=>`<article class="content-example"><span class="eyebrow">0${i+1} / ${esc(e.type)}</span><h4>${esc(e.title)}</h4><p>${esc(e.purpose)}</p><span class="example-creator">公开样例 · ${esc(e.creator)}</span><a class="text-link" href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">查看小红书帖文 ↗</a></article>`).join('')}</div><p class="data-note">公开样例按原帖作者署名展示；我的项目职责为选题策划、产品信息植入、Brief与内容审核等。</p></div>`;
  }
  function contentReview(review){
    return `<div class="content-review"><div class="eyebrow">CONTENT REVIEW / 历史复盘</div><h3>从单篇表现到可复用的内容判断</h3><p class="data-note">${esc(review.note)}</p><article class="review-feature"><h4>${esc(review.tutorial.title)}</h4><div class="review-stats">${review.tutorial.metrics.map(([n,l])=>`<div><strong>${esc(n)}</strong><span>${esc(l)}</span></div>`).join('')}</div><p>${esc(review.tutorial.body)}</p></article><article class="review-feature"><h4>${esc(review.mix.title)}</h4><div class="content-mix">${review.mix.parts.map(([n,l])=>`<span><b>${esc(n)}</b>${esc(l)}</span>`).join('')}</div><div class="review-table-wrap"><table class="review-table"><thead><tr><th>内容类型</th><th>阅读量</th><th>复盘观察</th></tr></thead><tbody>${review.cases.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>复盘启发：时效资讯承接节点关注，教程通过搜索获得长尾流量，而开通指南的价值还体现在用户咨询，评估内容时需要同时观察触达与使用意向。</p></article><details class="story-block review-evidence"><summary><span>查看原始复盘截图</span><span class="story-plus" aria-hidden="true">+</span></summary><div class="review-images">${review.images.map(([src,caption])=>image(src,caption)).join('')}</div></details></div>`;
  }
  function topicEvidence(topic){
    return topic?`<div class="topic-evidence"><div class="eyebrow">CAMPAIGN / 话题成果</div><h3>${esc(topic.title)}</h3><div class="topic-stat"><strong>${esc(topic.value)}</strong><span>${esc(topic.label)}</span></div><p class="data-note">${esc(topic.note)}</p>${image(topic.image,'早餐短剧 · 话题成果截图（用户提供，截图时间未提供）')}</div>`:'';
  }
  function projectVideos(project){
    return `<div class="project-videos"><h3>本人制作与剪辑</h3>${(project.videos||[project.video]).map(videoCard).join('')}${project.ugcVideo?`<h3 class="ugc-heading">Prompt驱动的UGC创作</h3>${videoCard(project.ugcVideo)}`:''}</div>`;
  }
function accountCards(kind){return data.accounts.filter(a=>a.kind===kind).map(a=>`<article class="account-card"><div class="account-platform ${a.platform==='抖音'?'douyin':'xiaohongshu'}" aria-hidden="true">${a.platform==='抖音'?'♪':'RED'}</div><div class="account-copy"><h3>${esc(a.label)}</h3><span class="eyebrow">${esc(a.platform)}｜${esc(a.positioning||'内容创作')}｜${esc(a.role)}</span>${a.platformId?`<p class="account-id">${a.platform==='抖音'?'抖音号':'小红书号'}：${esc(a.platformId)}</p>`:''}<p>${esc(a.description)}</p>${a.metrics?.length?`<div class="account-metrics">${a.metrics.map(([n,l])=>`<span><b>${esc(n)}</b>${esc(l)}</span>`).join('')}</div><p class="data-note">${esc(a.metricNote)}</p>`:''}${a.previewNote?`<p class="subtle-note">${esc(a.previewNote)}</p>`:''}<a class="text-link" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc('打开'+a.label+'主页')}">${tr('查看账号主页','Open account profile')} ↗</a></div></article>`).join('');}
  function lab(){
    const nova=data.projects.find(p=>p.id==='nova');
    return `<article class="lab-page page-enter"><a class="back" href="#/">← ${tr('返回首页','Back home')}</a><span class="eyebrow">CREATIVE LAB / CONTENT EXPERIMENTS</span><h1>${tr('在自己的账号里，持续观察用户反馈','Learning from feedback on my own accounts.')}</h1><p class="lab-lead">${esc(tr('账号与内容作品','Accounts & Creative Work'))}</p><p class="lab-intro">${tr('从选题、制作到发布与复盘，我也通过账号实践，观察不同内容如何获得关注，以及用户愿意为什么表达观点、收藏和分享。','Some work starts with a business goal; some starts with curiosity. Here are experiments in AI video, new media, accounts and digital work.')}</p><nav class="lab-index" aria-label="Creative Lab"><a href="#/lab?section=lab-video">01 / AI Experiments</a><a href="#/lab?section=lab-incubation">02 / Social Media & Content</a><a href="#/lab?section=lab-visual">03 / Visual Storytelling</a></nav><section id="lab-video" class="case-section"><h2><span>01</span>AI Experiments</h2><div class="v2-prose"><h3>${tr("我的个人作品集网站","My portfolio website")}</h3>${copyHTML(tr(data.v2.siteExperiment,data.v2.siteExperimentEn))}<h3>${tr("AI影像创作","AI image & video creation")}</h3><p>${tr("以下包含商业项目中的创作实践，具体职责和项目成果单独标注。","The work below includes commercial project contributions, with roles and campaign results identified separately.")}</p></div><p>从创意构思、AI生成到素材调整、后期剪辑和最终交付，展示AI与商业内容制作的结合。</p><div class="production-flow">${data.lab.workflow.map((s,i)=>`<span><b>0${i+1}</b>${esc(s)}</span>`).join('')}</div>${projectVideos(nova)}<details class="story-block"><summary><span>话题累计成果与截图口径</span><span class="story-plus" aria-hidden="true">+</span></summary>${topicEvidence(nova.topic)}</details><p><a class="text-link" href="#/project/nova">查看Nova AI产品GTM准备案例 ↗</a></p></section><section id="lab-incubation" class="case-section"><h2><span>02</span>Social Media & Content</h2><h3>${tr("AI内容账号孵化","AI-assisted account incubation")}</h3><p>围绕垂直领域进行账号定位、内容规划、AI素材制作和平台发布，通过选题与SEO优化探索低成本的内容增长方式。</p><div class="metrics lab-metrics">${data.lab.incubationMetrics.map(([n,l])=>`<div class="metric"><strong>${esc(n)}</strong><span>${esc(l)}</span></div>`).join('')}</div><p class="data-note">以上为两个财经垂类AI账号的合计实践成果，不是当前主页实时粉丝数。</p><div class="account-grid">${accountCards('incubated')}</div><details class="lab-review"><summary>冷启动复盘：定位 → 内容 → 搜索 → 反馈 <span>+</span></summary><div class="actions"><div><h3>先明确账号定位</h3><p>围绕财经资讯与金融知识，建立目标用户能理解的垂直方向。</p></div><div><h3>用AI辅助生产</h3><p>结合热点组织脚本、图文素材与视频，降低生产成本。</p></div><div><h3>根据反馈迭代</h3><p>观察内容互动与搜索表现，调整标题、关键词及后续选题。</p></div></div><a class="text-link" href="#/project/futu">查看富途项目中的增长实验 ↗</a></details></section><section id="lab-operations" class="case-section"><h3>${tr("品牌账号内容与视频制作","Brand accounts & video production")}</h3><p>参与账号运营，并负责品牌系列故事、大空间系列故事、消费者感受、B端招商和产品介绍视频。这里将账号运营职责与本人制作的视频类型分开标注。</p><div class="content-types">${['品牌系列故事','大空间系列故事','消费者感受','B端招商','产品介绍视频'].map(t=>`<span>${t}</span>`).join('')}</div><div class="account-grid">${accountCards('operated')}</div></section><section id="lab-personal" class="case-section personal-work"><h3>${tr("个人内容账号","Personal content account")}</h3><p>持续关注社交媒体趋势，探索内容创意、视觉表达与用户反馈之间的关系。</p><div class="personal-metrics">${data.lab.personalMetrics.map(([n,l])=>`<div><strong>${esc(n)}</strong><span>${esc(l)}</span></div>`).join('')}</div><div class="account-grid">${accountCards('personal')}</div><p class="data-note">个人创作的累计成果独立展示，不与项目账号运营或财经账号孵化数据合并。</p></section><section id="lab-visual" class="case-section"><h2><span>03</span>Visual Storytelling</h2><p>从节日玩法、AI场景资产到品牌传播海报，保留作品本身的视觉信息。点击图片可放大查看。</p><div class="filters" role="group" aria-label="筛选作品">${[['all','全部','All'],['ai','AI创意','AI creative'],['campaign','品牌传播','Campaign']].map(([k,z,e])=>`<button class="filter" data-gallery-filter="${k}" aria-pressed="${galleryFilter===k}">${tr(z,e)}</button>`).join('')}</div><div class="gallery-grid" id="gallery-grid">${galleryMarkup()}</div></section></article>`;
  }
function originalDetail(p){
    const idx=data.projects.indexOf(p),next=data.projects[(idx+1)%data.projects.length];
    const sections=[['case-context','01 项目背景与业务目标'],['case-judgment','02 核心问题与个人判断'],['case-action','03 我的行动'],['case-evidence','04 关键证据'],['case-results','05 项目结果与复盘']];
    const records=`<div class="case-stories">${p.stories.map(story=>`<details class="story-block"><summary><span>${esc(story.heading.replace(/_/g,' '))}</span><span class="story-plus" aria-hidden="true">+</span></summary><div class="story-body">${markdownNotes(story.body)}</div></details>`).join('')}</div>`;
    const sop=`<div id="case-sop" class="sop">${p.sop.map(([h,b,o],i)=>`<details class="sop-step" ${i===0?'open':''}><summary><span class="step-number">0${i+1} →</span><strong>${esc(h)}</strong><span class="step-toggle" aria-hidden="true">+</span></summary><p>${esc(b)}</p><div class="step-output">${tr('产出','Output')} / ${esc(o)}</div></details>`).join('')}</div><p class="sop-hint">${tr('点击流程节点，展开行动与产出。','Select a step to view actions and outputs.')}</p>`;
    return `<article class="detail page-enter"><a class="back" href="#projects">← ${tr('返回案例列表','Back to cases')}</a><div class="detail-meta"><span class="eyebrow">${esc(p.category)}</span><span class="eyebrow muted">${esc(p.company)}</span></div><h1>${esc(title(p))}</h1><p class="detail-lead">${esc(tr(p.summary,p.summaryEn))}</p><div class="facts"><div><span class="fact-label">MY CONTRIBUTION / ${tr('我的职责','My role')}</span><ul class="role-list">${p.responsibilities.map(role=>`<li>${esc(role)}</li>`).join('')}</ul></div><div><span class="fact-label">FOCUS</span><div class="tags">${chips(p)}</div></div></div>${p.cover?`<figure class="detail-cover ${p.tone}"><button data-image="${esc(p.cover)}" data-caption="${esc(p.coverLabel)}" aria-label="放大项目视觉"><img src="${esc(p.cover)}" alt="${esc(p.coverLabel)}"></button><figcaption>${esc(p.coverLabel)}</figcaption></figure>`:''}<nav class="case-index" aria-label="案例章节">${sections.map(([id,label],i)=>`<a href="${projectLink(p)}?section=${id}">${tr(label,`${i+1} ${['Context','Judgment','Actions','Evidence','Results'][i]}`)}</a>`).join('')}</nav><section id="case-context" class="case-section"><h2><span>01</span>${tr('项目背景与业务目标','Context & goals')}</h2><p>${esc(tr(p.intro,p.introEn))}</p><p class="project-goal"><strong>${tr('业务目标','Goal')}：</strong>${esc(p.goal)}</p>${p.id==='futu'?phaseCompare()+`<p class="data-note">${esc(p.phaseNote)}</p>`:''}</section><section id="case-judgment" class="case-section"><h2><span>02</span>${tr('核心问题与个人判断','Problem & judgment')}</h2><p>${esc(p.judgment)}</p>${p.chain?`<div class="production-flow">${p.chain.map((text,i)=>`<span><b>0${i+1}</b>${esc(text)}</span>`).join('')}</div>`:''}</section><section id="case-action" class="case-section"><h2><span>03</span>${tr('我的行动','My actions')}</h2><div class="actions">${p.actions.map(([h,b])=>`<div><h3>${esc(h)}</h3><p>${esc(b)}</p></div>`).join('')}</div>${sop}<h3 class="records-heading">${tr('完整实践记录','Detailed execution records')}</h3>${records}${p.id==='nova'?`<p class="data-note">${esc(p.processNote)}</p>`:''}</section><section id="case-evidence" class="case-section"><h2><span>04</span>${tr('关键证据','Evidence')}</h2>${p.id==='xiaomi'?evaluation():''}${p.contentExamples?contentMatrix(p)+`<h3 class="records-heading">AI账号孵化实物入口</h3><div class="account-grid">${accountCards('incubated')}</div><a class="text-link" href="#/lab?section=lab-incubation">查看账号与内容作品 ↗</a>`:''}${p.video?projectVideos(p):''}${p.gallery.length?`<div class="case-gallery ${p.gallery.length===1?'one':''}">${p.gallery.map(([src,caption])=>image(src,caption)).join('')}</div>`:''}${p.id==='baike'?'<div class="evidence-note"><h3>创作者运营手册与任务机制</h3><p>已有娱乐人物类、知识趣梗类运营手册与任务下发SOP，用于选题、标题封面、内容结构和审核指导。手册原件包含内部运营信息，网页以流程和完整实践记录呈现，未公开原始交接文件。</p></div>':''}</section><section id="case-results" class="case-section"><h2><span>05</span>${tr('项目结果与复盘','Results & reflection')}</h2><div class="metrics">${p.metrics.map(m=>`<div class="metric"><strong>${esc(tr(m[0],m[2]))}</strong><span>${esc(tr(m[1],m[3]))}</span></div>`).join('')}</div><p class="data-note">${esc(p.resultNote)}</p>${p.contentReview?contentReview(p.contentReview):''}${p.conversionNote?`<p class="data-note">${esc(p.conversionNote)}</p>`:''}${p.topic?`<details class="story-block"><summary><span>话题累计成果（独立统计口径）</span><span class="story-plus" aria-hidden="true">+</span></summary>${topicEvidence(p.topic)}</details>`:''}<div id="case-learning" class="case-reflection"><h3>${tr('可复用的判断','What I would reuse')}</h3><p>${esc(p.learning)}</p></div></section><p class="source-note">${tr('内容依据','Sources')} / ${esc(p.source)}</p><div class="project-next"><a href="#projects">← ${tr('全部案例','All cases')}</a><a href="${projectLink(next)}">${tr('下一个','Next')} / ${esc(next.company)} →</a></div></article>`;
  }
  function experience(){return data.experience.map(([date,company,role,work])=>`<div class="experience"><time>${esc(date)}</time><div><h3>${esc(company)} <span class="muted">/ ${esc(role)}</span></h3><p>${esc(work)}</p></div></div>`).join('');}
  function education(){return `<div class="education"><div><h3>北京师范大学</h3><p>广播电视与新媒体 · 硕士</p><p class="muted">2023.09—2026.07</p></div><div><h3>江汉大学</h3><p>播音与主持艺术 · 本科</p><p class="muted">2019.09—2023.07</p></div></div>`;}
  function originalAbout(){const a=data.about;return `<article class="about-page page-enter"><a class="back" href="#/">← ${tr('返回首页','Back home')}</a><div class="about-avatar" aria-hidden="true">YJ</div><span class="eyebrow">ABOUT / AI PRODUCT OPERATIONS · PRODUCT GROWTH</span><h1>${esc(tr(a.title,'From creative content to product operations and growth.'))}</h1><p class="about-intro">${esc(tr(a.intro,'With a master’s degree from Beijing Normal University and experience across Xiaomi, Baidu, moomoo and AI creation tools.'))}</p><p>${esc(a.body)}</p><p>我希望成为既理解产品，也理解用户的运营人才。</p><div class="hero-contact"><a class="chip" href="mailto:${data.email}">✉ ${data.email}</a><a class="chip" href="#/resume">${tr('查看简历 ↗','View resume ↗')}</a><a class="chip" href="#/lab">Creative Lab ↗</a></div><h2>${tr('我更关注的问题','The questions I care about')}</h2><ul class="about-questions">${a.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><h2>${tr('核心能力','Core capabilities')}</h2><div class="capability-list">${a.capabilities.map(([h,b],i)=>`<div><span>0${i+1}</span><div><h3>${esc(h)}</h3><p>${esc(b)}</p></div></div>`).join('')}</div><h2>${tr('工作与实践','Experience')}</h2>${experience()}<h2>${tr('教育经历','Education')}</h2>${education()}<h2>${tr('工具与方法','Tools & methods')}</h2><div class="tool-list">${data.tools.map(t=>`<span>${esc(t)}</span>`).join('')}</div><h2>AI Product Operations / Product Growth</h2><p>${esc(a.direction)}</p></article>`;}

  function copyHTML(text){return String(text||'').split(/^(#{2,3}) (.+)$/m).map((part,i,all)=>{if(i%3===1)return `<h${part.length}>${esc(all[i+1])}</h${part.length}>`;if(i%3===2)return '';return markdownNotes(part.replace(/^\d+\. /gm,'- '));}).join('');}
  const creatorBriefs=[{id:'entertainment',zh:'娱乐人物类账号运营手册',en:'Entertainment creator brief',pdf:'assets/baidu-entertainment-brief.pdf',cover:'assets/baidu-entertainment-cover.jpg'},{id:'knowledge',zh:'知识趣梗类账号运营手册',en:'Knowledge creator brief',pdf:'assets/baidu-knowledge-brief.pdf',cover:'assets/baidu-knowledge-cover.jpg'}];
  function briefCards(){return `<div id="case-evidence" class="creator-briefs"><h3>${tr('发给创作者的内容 Brief','Creator content briefs')}</h3><p>${tr('百度校园知识合伙人项目下发给达人的内容指导材料，包含账号参考、内容制作流程与选题方向。','Content guidance distributed to creators in the Baidu campus knowledge partner program, including account references, production workflows and topic directions.')}</p><div class="brief-grid">${creatorBriefs.map(b=>`<a class="brief-card" href="#/brief/${b.id}"><img src="${b.cover}" alt="${esc(tr(b.zh,b.en))}"><span class="eyebrow">PDF / 8 ${tr('页','PAGES')}</span><h4>${esc(tr(b.zh,b.en))}</h4><span class="text-link">${tr('打开阅读页','Read brief')} ↗</span></a>`).join('')}</div></div>`;}
  function briefReader(id){const b=creatorBriefs.find(b=>b.id===id);return `<article class="brief-reader page-enter"><a class="back" href="#/project/baike?section=case-evidence">← ${tr('返回百度创作者项目','Back to the Baidu creator project')}</a><span class="eyebrow">CREATOR BRIEF / PDF</span><h1>${esc(tr(b.zh,b.en))}</h1><p>${tr('百度校园知识合伙人项目 · 达人内容指导材料 · 8页','Baidu campus knowledge partner program · Creator guidance · 8 pages')}</p><div class="reader-actions"><a class="primary-button" href="${b.pdf}" target="_blank" rel="noopener">${tr('新窗口查看PDF','Open PDF')} ↗</a><a class="text-link" href="${b.pdf}" download>${tr('下载PDF','Download PDF')} ↓</a></div><object class="pdf-document" data="${b.pdf}" type="application/pdf" aria-label="${esc(tr(b.zh,b.en))}"><p>${tr('此浏览器不支持内嵌PDF，可使用上方入口查看或下载。','Use the links above if your browser cannot display the PDF inline.')}</p></object></article>`;}
  function detail(p){
    const old=originalDetail(p),z=p.v2Sections,e=p.v2En;
    const start=old.indexOf('<nav class="case-index"'),end=old.indexOf('<p class="source-note">');
    const prefix=old.slice(0,start).replace(/<div class="facts">[\s\S]*?<\/div><\/div>/,'');
    let evidence=old.slice(old.indexOf('<section id="case-evidence"'),old.indexOf('<section id="case-results"')).replace(/<section[^>]+><h2>[\s\S]*?<\/h2>/,'<div id="case-evidence" class="process-evidence">').replace(/<\/section>$/,'</div>');
    if(p.id==='futu')evidence=evidence.replace('</div>',image('assets/futu-team.jpg',tr('富途团队合照 · 用户提供','Futu team photo · provided by Janice'))+'</div>');
    if(p.evidenceGroups)evidence=`<div id="case-evidence" class="heritage-evidence">${p.evidenceGroups.map((g,i)=>`<section class="heritage-group heritage-group-${i}"><h3>${esc(tr(g.title,g.titleEn))}</h3><div class="heritage-media">${g.items.map(([n,zh,en])=>image(n,tr(zh,en),'heritage-item-'+n.match(/(\d+)\.png$/)[1])).join('')}</div></section>`).join('')}</div>`;
    if(p.experienceEvidence)evidence='<div class="xiaomi-experience"><h3>'+tr('从入口到完成生成','From entry to generated output')+'</h3>'+p.experienceEvidence.map(([src,zh,en],i)=>image(src,tr(zh,en),i===0?'experience-flow':'experience-entry')).join('')+'</div>'+evidence;
    if(p.id==='nova')evidence+=`<div class="breakfast-posters"><h3>${tr('早餐短剧 · 项目海报','Breakfast series · project posters')}</h3><div>${image('assets/breakfast-poster-3.png',tr('《早餐继承者们》第二集 · 项目海报','Breakfast series · episode 2 poster'))}${image('assets/breakfast-poster-4.png',tr('《早餐继承者们》第一集 · 项目海报','Breakfast series · episode 1 poster'))}</div></div>`;
    if(p.id==='baike')evidence=briefCards();
    const sop=p.id==='baike'?`<div id="case-sop" class="sop">${p.sop.map(([h,b,o],i)=>`<details class="sop-step" ${i===0?'open':''}><summary><span class="step-number">0${i+1}</span><strong>${esc(h)}</strong></summary><p>${esc(b)}</p><p>${esc(o)}</p></details>`).join('')}</div>`:'';
    const blocks=[['case-context','项目概览','Project Overview',tr(z['项目背景'],e.context)],['case-role','我的职责','My Role',tr(p.responsibilities.map(x=>'- '+x).join('\n'),e.role)],['case-action','执行过程','The Process',tr(z['我的工作'],e.process)],['case-results','项目成果','The Outcome',tr(z['项目成果']||'项目以AI应用场景传播与执行成果为主，详见项目素材。',e.results)],['case-learning','复盘思考','Reflection',tr(z['我的复盘'].split('\n\n').slice(0,2).join('\n\n'),e.reflection)]];
    const nav=`<nav class="case-index" aria-label="${tr('案例章节','Case sections')}">${blocks.map(([id,zh,en])=>`<a href="${projectLink(p)}?section=${id}">${tr(zh,en)}</a>`).join('')}</nav>`;
    const body=blocks.map(([id,zh,en,copy],i)=>`<section id="${id}" class="case-section v2-prose"><h2><span>0${i+1}</span>${tr(zh,en)}</h2>${id==='case-context'?'<span id="case-judgment"></span>':''}${copyHTML(copy)}${id==='case-action'?sop+evidence+(p.contentReview?contentReview(p.contentReview):'')+(p.id==='futu'?phaseCompare()+`<p class="data-note">${esc(tr(p.phaseNote,'The comparison records content timing, not a controlled conversion experiment.'))}</p>`:''):''}${id==='case-results'?`<p class="data-note">${esc(tr(p.resultNote,e.scope))}</p>${p.funnelEvidence?image(p.funnelEvidence[0],tr(p.funnelEvidence[1],p.funnelEvidence[2]),'xiaomi-funnel')+`<p class="data-note">${tr('漏斗图为六一活动页面行为UV，保存点击UV不是生成图片张数，也不同于品牌转化UV。','The funnel reports page-behavior UV. Save-click UV is distinct from generated-image counts and brand conversion UV.')}</p>`:''}${p.conversionNote?`<p class="data-note">${esc(tr(p.conversionNote,e.scope))}</p>`:''}`:''}</section>`).join('');
    return prefix+nav+body+old.slice(end);
  }
  function narrativeSections(items,kind){return items.map((item,i)=>{const project=data.projects.find(p=>p.id===(kind==='method'?['xiaomi','nova','baike','futu']:['futu','xiaomi','nova','heritage'])[i]);const src=kind==='method'?(project.cover||(project.id==='baike'?'assets/baidu-entertainment-cover.jpg':project.contentReview.images[0][0])):['assets/janice-personal-1.jpg','assets/futu-team.jpg','assets/janice-personal-5.jpg','assets/janice-personal-3.jpg'][i];const caption=kind==='method'?tr(project.coverLabel||(project.id==='baike'?'百度创作者 · 娱乐人物类内容Brief':'富途 · 内容复盘原始截图'),project.titleEn):tr(['个人生活记录','富途团队合照','个人旅行记录','个人生活记录'][i],['Personal moments','Futu team photo','Personal travel photo','Personal moments'][i]);return `<section class="narrative-section ${i%2?'reverse':''}"><div class="narrative-heading"><span class="eyebrow">0${i+1} / ${kind==='method'?['UNDERSTAND','CREATE','CONNECT','IMPROVE'][i]:['EXPRESSION','EXPERIENCE','EXPLORATION','LOOKING FORWARD'][i]}</span><h2>${esc(tr(item.title,item.titleEn))}</h2>${i<3||kind==='method'?image(src,caption):''}</div><div class="narrative-body">${copyHTML(tr(item.body,item.bodyEn))}${kind==='method'?`<a class="text-link" href="${projectLink(project)}">${tr('相关实践','Related work')} / ${esc(project.company)} ↗</a>`:''}</div></section>`}).join('');}
  function about(){return `<article class="narrative-page page-enter"><div class="about-opening"><header class="editorial-intro"><span class="eyebrow">${tr('关于我','About Me')}</span><h1>Curious by nature.<br>Driven by creation.</h1><p>${tr('我喜欢探索新技术，也喜欢把复杂的想法变成真实、可感知的作品。','I enjoy exploring new technologies and turning complex ideas into tangible work.')}</p><p>${tr('从广播电视与新媒体出发，我逐渐走向AI产品、用户体验与增长实践。不同领域的经历让我学会从多个角度理解问题，也让我越来越关注技术如何真正服务于人。','Starting in broadcasting and new media, I have moved toward AI products, user experience and growth. Working across different fields has taught me to look at problems from several perspectives and ask how technology can serve people.')}</p></header><figure class="about-portrait"><img src="assets/janice-personal-3.jpg" alt="${tr('Janice个人照片','Portrait of Janice')}"><figcaption>邱雅婧 / Janice Qiu</figcaption></figure></div>${narrativeSections(data.editorial.about,'about')}<div class="page-end"><p>Always learning. Always creating.</p><a class="text-link" href="#/work">${tr('保持好奇，继续创造。浏览作品','Explore my work')} ↗</a></div></article>`;}
  function approach(){return `<article class="narrative-page page-enter"><header class="editorial-intro"><span class="eyebrow">${tr('能力与方法','How I Work')}</span><h1>Think.<br>Make.<br>Improve.</h1><p>${tr('从理解问题，到创造解决方案，再到通过反馈持续优化。','Understand the problem, make a solution, then improve through feedback.')}</p></header>${narrativeSections(data.editorial.methods,'method')}<div class="page-end"><p>Less about doing more.<br>More about making things work.</p><span>${tr('不只是完成更多任务，而是让每一次行动真正产生价值。','Making each action useful.')}</span></div></article>`;}
  function contact(){return `<article class="contact-page page-enter"><div class="contact-portrait">${image('assets/janice-personal-2.jpg',tr('个人生活记录','Personal moments'))}</div><header class="editorial-intro"><span class="eyebrow">${tr('保持联系','Get in Touch')}</span><h1>Let’s make something meaningful.</h1><p>${tr('我对AI产品、用户体验、内容增长和数字创意充满兴趣，也期待与有趣的产品、团队和想法相遇。','I’m interested in AI products, user experience, content growth and digital creativity, and look forward to meeting thoughtful teams and ideas.')}</p><p>${tr('如果你正在寻找一个善于理解用户、热爱创意并重视落地的人，欢迎联系我。','If you are looking for someone who cares about users, creativity and practical delivery, let’s connect.')}</p></header><p>邱雅婧 / Janice Qiu</p><p>${tr('北京师范大学 · 广播电视新媒体硕士','Beijing Normal University · Master’s in Broadcasting & New Media')}</p><div class="contact-actions"><a href="${esc(data.resume.url)}" target="_blank" rel="noopener">${tr('查看简历PDF','View resume PDF')} ↗</a><a href="mailto:${esc(data.email)}">${esc(data.email)} ↗</a><a href="https://github.com/onyourjanice-star" target="_blank" rel="noopener noreferrer">GitHub ↗</a><button data-action="copy-url">${tr('复制作品集链接','Copy portfolio link')} ↗</button></div></article>`;}
  function resume(){return `<article class="about-page page-enter"><a class="back" href="#/">← ${tr('返回首页','Back home')}</a><div class="resume-top"><div><span class="eyebrow">RESUME / 2026</span><h1>邱雅婧 <span class="muted">/ Yajing Qiu</span></h1></div><a class="primary-button" href="${esc(data.resume.url)}" download="${esc(data.resume.filename)}">${tr('下载PDF简历','Download PDF')}</a><button class="print-button" data-action="print">${tr('打印 / 保存PDF','Print / Save PDF')}</button></div><p class="about-intro">${tr('AI产品运营｜AI应用体验与内容增长','AI Product Operations | AI Experiences & Content-led Growth')}</p><p class="data-note">${esc(data.resume.note)}</p><a class="text-link" href="mailto:${data.email}">${data.email}</a><h2>${tr('教育背景','Education')}</h2>${education()}<h2>${tr('工作经历','Experience')}</h2>${experience()}<h2>${tr('代表项目','Selected projects')}</h2>${data.projects.map(p=>`<section class="resume-project"><h3><a href="${projectLink(p)}">${esc(title(p))} ↗</a></h3><p>${esc(tr(p.role,p.roleEn))}</p><ul>${p.metrics.slice(0,2).map(m=>`<li>${esc(tr(m[1],m[3]))}：${esc(tr(m[0],m[2]))}</li>`).join('')}</ul><p class="muted">${esc(p.resultNote)}</p></section>`).join('')}<h2>${tr('工具','Tools')}</h2><p>${data.tools.map(esc).join(' · ')}</p></article>`;}
function parseRoute(hash){
    if(hash==='#projects')return {type:'work',section:'projects'};
    if(hash==='#gallery')return {type:'lab',section:'lab-visual'};
    const [route,query='']=hash.split('?'),section=new URLSearchParams(query).get('section')||'';
    const briefMatch=route.match(/^#\/brief\/(entertainment|knowledge)$/);
    if(briefMatch)return {type:'brief',id:briefMatch[1],section:''};
    const match=route.match(/^#\/project\/([a-z]+)$/);
    if(match)return {type:'project',id:match[1]==='creative'?'nova':match[1],section:/^case-[a-z-]+$/.test(section)?section:''};
    if(route==='#/lab')return {type:'lab',section:/^lab-[a-z-]+$/.test(section)?section:''};
    if(route==='#/work')return {type:'work',section:/^work-(ai|growth|story)$/.test(section)?section:''};
    if(route==='#/approach')return {type:'approach',section:''};
    if(route==='#/contact')return {type:'contact',section:''};
    if(route==='#/about')return {type:'about',section:''};
    if(route==='#/resume')return {type:'resume',section:''};
    return {type:'home',section:''};
  }
  const routeScroll=new Map();let activeRouteKey='',clickedNavigation=false;
  if('scrollRestoration' in history)history.scrollRestoration='manual';
  function render({restore=false,preserveScroll=false,force=false}={}){
    updateChrome();const hash=location.hash,route=parseRoute(hash),key=route.type+(route.id||''),currentY=window.scrollY;
    if(force||key!==activeRouteKey){
      let html;
      if(route.type==='project'){const p=data.projects.find(p=>p.id===route.id);html=p?detail(p):`<article class="about-page"><h1>${tr('没有找到这个案例','Case not found')}</h1><a class="text-link" href="#projects">${tr('返回项目','Back to cases')} →</a></article>`;document.title=p?`${title(p)} · JANICE`:'未找到案例 · JANICE';}
      else if(route.type==='brief'){html=briefReader(route.id);document.title='Creator Brief · JANICE';}
      else if(route.type==='work'){html=work();document.title='作品与项目 · JANICE';}
      else if(route.type==='approach'){html=approach();document.title='能力与方法 · JANICE';}
      else if(route.type==='contact'){html=contact();document.title='保持联系 · JANICE';}
      else if(route.type==='lab'){html=lab();document.title='Creative Lab · JANICE';}
      else if(route.type==='about'){html=about();document.title='关于 · JANICE';}
      else if(route.type==='resume'){html=resume();document.title='简历 · JANICE';}
      else{html=home();document.title='JANICE · AI产品运营作品集';}
      main.innerHTML=html;activeRouteKey=key;
    }
    requestAnimationFrame(()=>{
      if(preserveScroll)window.scrollTo({top:currentY,behavior:'instant'});
      else if(restore&&routeScroll.has(hash))window.scrollTo({top:routeScroll.get(hash),behavior:'instant'});
      else if(route.section)document.getElementById(route.section)?.scrollIntoView({behavior:'instant',block:'start'});
      else window.scrollTo({top:0,behavior:'instant'});
    });
  }
  function showBrief(){const el=document.querySelector('#brief-dialog');document.querySelector('#brief-content').innerHTML=`<span class="eyebrow">A QUICK INTRODUCTION</span><h2>${tr('你好，我是邱雅婧。','Hi, I’m Yajing.')}</h2><p>${tr('关注AI产品运营与产品增长，希望让产品更容易被理解、使用和传播。','I focus on AI product operations, product growth and GTM, connecting product capabilities with user scenarios and creator ecosystems.')}</p><div class="brief-copy" id="brief-copy"><strong>${tr('你可以从这些方向了解我：','Explore my work through:')}</strong><ul><li>${tr('小米：产品场景、AI玩法和生成效果评估。','Xiaomi: AI scenarios, playful experiences and output evaluation.')}</li><li>${tr('富途：围绕业务节点的内容策略、KOC矩阵与搜索反馈。','moomoo: content strategy, KOC operations and search feedback.')}</li><li>${tr('Nova AI：创作场景探索、GTM准备与创作者合作。','Nova AI: creative use cases, GTM preparation and creator collaboration.')}</li><li>${tr('百度百科：创作者运营、内容SOP与激励机制。','Baidu: creator operations, content SOP and incentives.')}</li></ul><p>北京师范大学 · 广播电视与新媒体硕士<br>${data.email}</p></div><button class="primary-button" data-action="copy-brief">${tr('复制这份简介','Copy introduction')}</button> <a class="text-link" href="#/about" data-close-dialog>${tr('查看完整经历','Full experience')} ↗</a>`;el.showModal();}
  function showToast(message){const toast=document.querySelector('#toast');toast.textContent=message;toast.hidden=false;setTimeout(()=>toast.hidden=true,2500);}
  const answers={
    nova:{match:/Nova|GTM|市场启动|短剧|视频|video/i,text:'Nova AI案例展示AI视频工具的创作场景与市场启动准备。我参与创意脚本、AI素材生成剪辑、创作者合作和模板准备。早餐Campaign交付3支达人视频、1支官方宣传片，累计445篇UGC；成片链接已放入案例与Creative Lab。',en:'The Nova AI case covers creative workflows and GTM preparation, with scripts, AI production and creator collaboration. Explore the case for the breakfast campaign and video link.',link:'nova'},
    lab:{match:/账号|孵化|小红书|抖音|作品|实验室|lab|account/i,text:'Creative Lab区分两个小红书独立孵化账号与两个参与运营的抖音账号。品牌系列故事、大空间系列故事、消费者感受、B端招商及产品介绍视频由我制作；个人创作数据单独呈现。',en:'Creative Lab separates independently incubated Xiaohongshu accounts from Douyin accounts I helped operate, alongside project videos and personal work.',href:'#/lab'},
    ai:{match:/AI|小米|场景|玩法|评估|模型/i,text:'小米项目侧重把AI生图能力转化为旅行拍立得、童年手办等可参与场景。我参与玩法方案、测试集建设、生成效果评估与传播协同。',en:'The Xiaomi project connects AI generation with travel photos and childhood collectibles. My contribution includes scenario planning, test sets, evaluation and communications.',link:'xiaomi'},
    growth:{match:/增长|富途|moomoo|搜索|IPO|内容策略/i,text:'富途案例围绕IPO节点，组织资讯、申购教程和结果讨论，协同KOC内容分发并根据反馈调整节奏。专题曝光约54万；搜索变化为传播周期观测，不单独归因。',en:'The moomoo case covers IPO content strategy, KOC distribution and iteration. The campaign recorded about 540K KOC impressions. Search changes are observational, not a claim of single-channel attribution.',link:'futu'},
    creator:{match:/百度|创作者|百科|机制|SOP|社群/i,text:'百度百科项目展示创作者招募、内容指导、任务审核、数据回收与激励反馈。项目累计站外内容5572篇，我的贡献侧重运营机制与日常执行。',en:'The Baidu case covers recruitment, content guidance, briefs, review, reporting and incentives. 5,572 posts is the project total, not my personal writing output.',link:'baike'},
    contact:{match:/联系|邮箱|简历|求职|机会|contact|resume|email/i,text:`可以通过 ${data.email} 联系我。关注AI产品运营、产品增长、产品GTM及创作者生态相关机会。`,en:`Contact me at ${data.email}. Interested in AI operations, content operations and growth.`,href:'#/resume'},
    video:{match:/视频|短剧|创意|制作|video|creative/i,text:'AI商业内容案例包含早餐短剧角色与场景素材。我参与创意脚本、AI生成、素材筛选及剪辑，协助达人视频与官方宣传片制作。',en:'The AI commercial case includes breakfast-series characters and scenes. I contributed to scripts, AI assets, selection and editing for creator and campaign videos.',link:'nova'}
  };
  function guideAnswer(question,key){const a=answers[key]||[answers.nova,answers.growth,answers.creator,answers.lab,answers.ai,answers.contact].find(a=>a.match.test(question));return a?{text:tr(a.text,a.en),href:a.href||`#/project/${a.link}`}:{text:tr('我可以带你了解AI玩法、内容增长、创作者运营或联系方式。这里是依据作品集内容的本地导览，未收录的信息不会补写。','I can help you explore AI experiences, content growth, creator operations or contact information. This is a local guide based on the portfolio, not an external AI service.'),href:'#projects'};}
  function renderGuide(){const el=document.querySelector('#guide');el.innerHTML=`<div class="guide-head"><strong>✳ ${tr('雅婧的作品集导览','Yajing’s portfolio guide')}</strong><small>${tr('从项目与经历出发，找到你关心的内容。','Find the projects and experience you care about.')}</small><button data-action="guide" aria-label="关闭导览">×</button></div><div class="guide-body" aria-live="polite"><div class="message">${tr('你好，想先了解哪一部分？我可以帮你找到相关项目。','Hi! What would you like to explore? I can point you to a relevant project.')}</div><div class="suggestions">${[['ai','查看 AI 产品策划经验'],['creator','查看创作者运营经验'],['nova','查看 AI 视频创作经验']].map(([key,q])=>`<button data-guide-key="${key}" data-question="${q}">${q}</button>`).join('')}</div>${guideHistory.map(m=>`<div class="message ${m.user?'user':''}">${esc(m.text)}${m.href?`<br><a href="${m.href}">${tr('查看相关内容','View related content')} →</a>`:''}</div>`).join('')}</div><form class="guide-form"><input name="question" aria-label="输入导览问题" placeholder="${tr('输入你关心的方向…','What are you interested in?')}" maxlength="300" required><button type="submit">${tr('发送','Send')}</button></form><div class="guide-foot">${tr('基于站内内容的本地导览 · 不调用外部AI服务','Local, portfolio-based guide · no external AI calls')}</div>`;const body=el.querySelector('.guide-body');body.scrollTop=body.scrollHeight;}
  function askGuide(q,key){const answer=guideAnswer(q,key);guideHistory.push({user:true,text:q},answer);renderGuide();document.querySelector('.guide-form input')?.focus();}
  document.addEventListener('click',async e=>{
    const target=e.target.closest('button,a');if(!target)return;
    if(target.dataset.action==='language'){lang=lang==='zh'?'en':'zh';try{localStorage.setItem('yajing-language',lang);}catch{}render({force:true,preserveScroll:true});if(!document.querySelector('#guide').hidden)renderGuide();}
    if(target.dataset.action==='brief')showBrief();
    if(target.dataset.action==='close')target.closest('dialog').close();
    if(target.hasAttribute('data-close-dialog'))target.closest('dialog').close();
    if(target.dataset.action==='copy-brief'){try{await navigator.clipboard.writeText(document.querySelector('#brief-copy').innerText);showToast(tr('简介已复制','Introduction copied'));}catch{showToast(tr('请选中简介文字后复制','Select the introduction text to copy'));}}
    if(target.dataset.action==='copy-url'){try{await navigator.clipboard.writeText('https://onyourjanice-star.github.io/janice-portfolio/');showToast(tr('作品集链接已复制','Portfolio link copied'));}catch{showToast(tr('请复制浏览器地址栏中的网址','Copy the URL from your browser address bar'));}}
    if(target.dataset.action==='print')window.print();
    if(target.dataset.action==='guide'){const el=document.querySelector('#guide');el.hidden=!el.hidden;document.querySelector('.guide-toggle').setAttribute('aria-expanded',String(!el.hidden));if(!el.hidden){renderGuide();el.querySelector('input').focus();}}
    if(target.dataset.question)askGuide(target.dataset.question,target.dataset.guideKey);
    if(target.dataset.filter){filter=target.dataset.filter;document.querySelector('#project-list').innerHTML=filteredProjects();document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));}
    if(target.dataset.galleryFilter){galleryFilter=target.dataset.galleryFilter;document.querySelector('#gallery-grid').innerHTML=galleryMarkup();document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.galleryFilter===galleryFilter)));}
    if(target.dataset.image){const dialog=document.querySelector('#lightbox');dialog.querySelector('img').src=target.dataset.image;dialog.querySelector('img').alt=target.dataset.caption;dialog.querySelector('p').textContent=target.dataset.caption;dialog.showModal();}
    if(target.dataset.evaluation){document.querySelector('#evaluation-content').innerHTML=evaluationContent(target.dataset.evaluation);document.querySelectorAll('[data-evaluation]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));}
    if(target.dataset.phase){const second=target.dataset.phase==='2',pre=second?40:15;document.querySelectorAll('[data-phase]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));document.querySelector('#phase-pre b').textContent=pre+'%';document.querySelector('#phase-post b').textContent=(100-pre)+'%';const bar=document.querySelector('.phase-bar');bar.style.setProperty('--pre',pre+'%');bar.setAttribute('aria-label',`上市前${pre}%，上市后${100-pre}%`);document.querySelector('#phase-caption').textContent=second?tr('第二轮将上市前内容占比提升至40%，提前覆盖新股资讯和申购需求；仍需依据热度与平台规范动态调整。','Phase two increased pre-IPO content to 40%, covering information needs earlier. Execution remained responsive to demand and platform rules.'):tr('第一轮集中于上市后中签与收益讨论。','Phase one focused on post-IPO outcomes and discussions.');}
    const anchor=target.getAttribute('href');if(anchor==='#main'){e.preventDefault();main.focus();main.scrollIntoView();}
    if(anchor?.startsWith('#case-')||anchor?.startsWith('#lab-')){e.preventDefault();document.getElementById(anchor.slice(1))?.scrollIntoView({behavior:'instant'});return;}
    if(anchor?.startsWith('#')&&anchor!=='#main'){
      e.preventDefault();routeScroll.set(location.hash,window.scrollY);
      if(anchor===location.hash)render();else{clickedNavigation=true;location.hash=anchor;}
    }
  });
  document.addEventListener('submit',e=>{if(e.target.matches('.guide-form')){e.preventDefault();const q=new FormData(e.target).get('question').trim();if(q)askGuide(q);}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#guide').hidden){document.querySelector('#guide').hidden=true;document.querySelector('.guide-toggle').setAttribute('aria-expanded','false');document.querySelector('.guide-toggle').focus();}});
  document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}}));
  window.addEventListener('hashchange',event=>{const wasClick=clickedNavigation;clickedNavigation=false;if(!wasClick)routeScroll.set(new URL(event.oldURL).hash,window.scrollY);render({restore:!wasClick});});
  const syncNav=()=>document.documentElement.style.setProperty('--nav-height',document.querySelector('.nav').getBoundingClientRect().height+'px');
  new ResizeObserver(syncNav).observe(document.querySelector('.nav'));syncNav();
  render();
})();



